def moyenne(notes):
    if not notes:
        return 0
    return sum(notes) / len(notes)


def test_moyenne():
    assert moyenne([10, 10]) == 10


# Vérification fournie : ne la modifie pas.
MUTANTS = [
    lambda notes: 0,
    lambda notes: sum(notes) // len(notes) if notes else 0,
    lambda notes: sum(notes) / len(notes),
]


def evaluer_tests():
    global moyenne
    original = moyenne
    test_moyenne()
    resultats = []
    for mutant in MUTANTS:
        moyenne = mutant
        try:
            test_moyenne()
            resultats.append("raté")
        except Exception:
            resultats.append("détecté")
    moyenne = original
    return resultats

